// test_rustc_split_decls.rs - Test suite for rustc split-decls extraction
// Generated by step4_bootstrap - Rustc Split Decls

use split_decls_genesis::{
    mkrustc_full_split, mkdep_split_decls, mkfull_dep_tree, mkdeps_paths,
    extract_all_declarations_from_dependency, get_rustc_dependencies, extract_cargo_dependencies
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing rustc split-decls extraction...");
    
    // Test full rustc split-decls extraction
    println!("\n🦀 Extracting all rustc declarations:");
    let rustc_decls = mkrustc_full_split!();
    
    println!("\n📊 RUSTC SPLIT-DECLS RESULTS:");
    println!("  🔧 Total declarations: {}", rustc_decls.len());
    
    // Show sample declarations
    if !rustc_decls.is_empty() {
        println!("  📝 Sample declarations:");
        for (i, decl) in rustc_decls.iter().take(10).enumerate() {
            println!("    {}. {}", i+1, decl);
        }
        if rustc_decls.len() > 10 {
            println!("    ... and {} more", rustc_decls.len() - 10);
        }
    }
    
    // Count declaration types
    let mut type_counts = std::collections::HashMap::new();
    for decl in &rustc_decls {
        if let Some(decl_type) = decl.split('!').next() {
            *type_counts.entry(decl_type).or_insert(0) += 1;
        }
    }
    
    println!("\n📈 Declaration types breakdown:");
    for (decl_type, count) in type_counts {
        println!("  {} {}: {}", 
                 match decl_type {
                     "mkdeclfn" => "🔧",
                     "mkdeclstruct" => "🏗️",
                     "mkdeclenum" => "📋",
                     "mkdecltrait" => "🎯",
                     "mkdeclimpl" => "⚙️",
                     _ => "📦"
                 },
                 decl_type, count);
    }
    
    println!("\n🎉 Rustc split-decls extraction complete!");
    Ok(())
}
